//! Approval token primitives shared by the app shell (which mints) and the engine (which verifies).
//!
//! A token is a `rightkit-crypto` approval token (`v1.<issued>.<expires>.<base64url HMAC-SHA256>`) over
//! the draft kind, draft id, the SHA-256 of the draft's canonical inputs, and the single-use nonce the
//! engine issued at preflight; it expires after [`TOKEN_TTL_SECS`]. The secret is
//! generated by the app shell at every launch, held in its memory, and passed to the sidecar it
//! spawned over the private stdio pipe (`InitPayload::approval_secret`). SHA-256, HMAC and the
//! constant-time compare come from `rightkit-crypto`; randomness (the secret and each challenge nonce) comes from `rightkit-daemon`'s
//! `PrivateSecret::generate` (OS source, no fallback): if it fails, no nonce and no secret exist.
//!
//! What this guarantees: a caller of the engine's commands that does not hold the launch secret
//! cannot approve; a token is bound to one kind, draft id, input hash and nonce, expires, and is
//! single use.
//!
//! What this does NOT guarantee: the engine cannot authenticate whoever hands it the secret, and a
//! per-launch in-memory secret cannot be verified after that launch ends. Any process running as
//! the same user, with file and shell access, can start its own `<engine> --stdio`, give it
//! a secret it chose, mint tokens (the HMAC construction is public) and approve, or write the state
//! files directly. This is therefore not a boundary against arbitrary local code. It binds
//! approvals made through the engine's commands, which is how the agent plugin and other apps reach
//! the host.

use rightkit_crypto::{approval as rk, hex_encode, sha256};

/// Environment variable a DEBUG-build engine reads as a stand-in for the app's secret, so the e2e
/// suite can mint tokens. A release engine ignores it entirely (no environment marker enables it),
/// and a debug engine ignores it against the user's real data folder.
#[cfg(feature = "test-mode")]
pub const TEST_SECRET_ENV: &str = "RIGHTKIT_APPROVAL_TEST_SECRET";

/// Domain separator and version of the token message.
pub const TOKEN_DOMAIN: &str = "genright-approval-v1";

/// Shortest secret an engine accepts (hex characters).
pub const MIN_SECRET_LEN: usize = 32;

pub fn sha256_hex(bytes: &[u8]) -> String {
    hex_encode(&sha256(bytes))
}

/// Seconds a minted token stays valid; equals the engine's challenge lifetime.
pub const TOKEN_TTL_SECS: u64 = 30 * 60;

fn unix_now() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

/// Token purpose: the domain separator plus the approval kind.
fn purpose(kind: &str) -> String {
    format!("{TOKEN_DOMAIN}:{kind}")
}

/// Token subject: draft id, input hash and nonce, each length-prefixed so field edges are unambiguous.
fn subject(draft_id: &str, input_hash: &str, nonce: &str) -> String {
    format!(
        "{}:{draft_id}{}:{input_hash}{}:{nonce}",
        draft_id.len(),
        input_hash.len(),
        nonce.len()
    )
}

/// The approval token for one draft, its input hash and its challenge nonce: a `rightkit-crypto`
/// token (`v1.<issued>.<expires>.<mac>`) bound to the kind, draft id, input hash and nonce.
pub fn mint_token(
    secret: &str,
    kind: &str,
    draft_id: &str,
    input_hash: &str,
    nonce: &str,
) -> String {
    rk::mint(
        secret.as_bytes(),
        &purpose(kind),
        &subject(draft_id, input_hash, nonce),
        unix_now(),
        TOKEN_TTL_SECS,
    )
}

/// Constant-time, time-bound check of a presented token (`rightkit-crypto` verifies the MAC with
/// `ct_eq` and enforces the issue and expiry window).
pub fn token_matches(
    secret: &str,
    kind: &str,
    draft_id: &str,
    input_hash: &str,
    nonce: &str,
    presented: &str,
) -> bool {
    rk::verify(
        secret.as_bytes(),
        &purpose(kind),
        &subject(draft_id, input_hash, nonce),
        presented,
        unix_now(),
    )
    .is_ok()
}

// ---------------------------------------------------------------------------
// Canonical hashing and receipts shared by the engine's approvals module and providers
// ---------------------------------------------------------------------------

use serde_json::{json, Value};
use std::path::{Path, PathBuf};

/// Approval kind of the Blender product-spec confirmation (the spec's `confirmed` flag and every
/// finish's `approved` flag are released together by one in-app approval).
pub const BLENDER_KIND: &str = "blender_finish";

/// SHA-256 of the canonical JSON of a draft's approval inputs. The value first goes through the
/// serialize and parse a draft takes to and from disk, so a number that does not survive a round
/// trip bit-for-bit hashes the same at issue time and at approve time.
pub fn input_hash(inputs: &Value) -> String {
    let settled = serde_json::to_string(inputs)
        .ok()
        .and_then(|text| serde_json::from_str::<Value>(&text).ok())
        .unwrap_or_else(|| inputs.clone());
    sha256_hex(rightkit_crypto::canonical_json(&settled).as_bytes())
}

/// The approval inputs of a Blender product spec: the spec with every field the approval itself
/// sets removed (`confirmed`, `confirmed_by`, `confirmation`, and each finish's `approved`,
/// `approved_by`, `approval`). What is hashed is what the person saw: parts, slots, finish ids and
/// versions, owner, identity. A caller-set boolean is not part of it, so setting one changes nothing.
pub fn blender_spec_view(spec: &Value) -> Value {
    let mut stripped = spec.clone();
    if let Some(map) = stripped.as_object_mut() {
        for key in ["confirmed", "confirmed_by", "confirmation"] {
            map.remove(key);
        }
        if let Some(finishes) = map.get_mut("finishes").and_then(Value::as_object_mut) {
            for finish in finishes.values_mut() {
                if let Some(f) = finish.as_object_mut() {
                    for key in ["approved", "approved_by", "approval"] {
                        f.remove(key);
                    }
                }
            }
        }
    }
    json!({"kind": BLENDER_KIND, "spec": stripped})
}

/// Draft id of a Blender spec: the hash of its approval inputs, so a token for one spec cannot
/// approve another.
pub fn blender_draft_id(spec: &Value) -> String {
    input_hash(&blender_spec_view(spec))
}

fn safe_name(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 160
        && value
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
}

/// Path of the challenge file the engine's `approvals::issue` writes for a draft and nonce.
pub fn challenge_file(data_dir: &Path, kind: &str, draft_id: &str, nonce: &str) -> Option<PathBuf> {
    if !(safe_name(kind) && safe_name(draft_id) && safe_name(nonce)) {
        return None;
    }
    Some(
        data_dir
            .join("approvals")
            .join(kind)
            .join(format!("{draft_id}.{nonce}.json")),
    )
}

/// True when `record` is the approval record the engine's `approvals::consume` returned for exactly
/// this draft: the engine issued the challenge (file under `<data>/approvals/<kind>/` with the same
/// input hash), the token consumed it (its `.used` marker exists), and the record names that nonce
/// and hash. Writing a record is not enough: without an issued and consumed challenge for these
/// inputs it is refused, and a record copied onto an edited draft fails because the hash differs.
///
/// LIMIT: files, not a secret. A process that can write under the data folder can forge all three
/// files; see the host's approvals module. The per-launch secret cannot be checked here because
/// adoption can happen after the launch that minted the token ended.
pub fn receipt_valid(
    data_dir: &Path,
    kind: &str,
    draft_id: &str,
    expected_hash: &str,
    record: &Value,
) -> bool {
    let text = |key: &str| {
        record
            .get(key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|s| !s.is_empty())
    };
    let (Some(nonce), Some(hash), Some(rec_kind)) =
        (text("nonce"), text("input_hash"), text("kind"))
    else {
        return false;
    };
    if rec_kind != kind
        || hash != expected_hash
        || text("channel").is_none()
        || text("approved_at").is_none()
    {
        return false;
    }
    let Some(path) = challenge_file(data_dir, kind, draft_id, nonce) else {
        return false;
    };
    let Ok(body) = std::fs::read_to_string(&path) else {
        return false;
    };
    let Ok(challenge) = serde_json::from_str::<Value>(&body) else {
        return false;
    };
    if challenge["input_hash"].as_str() != Some(expected_hash)
        || challenge["nonce"].as_str() != Some(nonce)
    {
        return false;
    }
    let mut marker = path
        .file_name()
        .map(|n| n.to_os_string())
        .unwrap_or_default();
    marker.push(".used");
    path.with_file_name(marker).is_file()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn token_binds_every_field() {
        let secret = "s".repeat(MIN_SECRET_LEN);
        let t = mint_token(&secret, "recipes", "d1", "h1", "n1");
        assert!(token_matches(&secret, "recipes", "d1", "h1", "n1", &t));
        for (k, d, h, n) in [
            ("video", "d1", "h1", "n1"),
            ("recipes", "d2", "h1", "n1"),
            ("recipes", "d1", "h2", "n1"),
            ("recipes", "d1", "h1", "n2"),
        ] {
            assert!(!token_matches(&secret, k, d, h, n, &t));
        }
        assert!(!token_matches(
            "other-secret-other-secret-other-secret",
            "recipes",
            "d1",
            "h1",
            "n1",
            &t
        ));
        assert!(t.starts_with("v1."));
        let expired = rk::mint(
            secret.as_bytes(),
            &purpose("recipes"),
            &subject("d1", "h1", "n1"),
            1,
            10,
        );
        assert!(
            !token_matches(&secret, "recipes", "d1", "h1", "n1", &expired),
            "an expired token is refused"
        );
    }

    fn temp(label: &str) -> PathBuf {
        let dir =
            std::env::temp_dir().join(format!("rightkit-approval-{label}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    fn spec() -> Value {
        json!({"schema": 1, "owner": "adrian", "product_id": "p", "variant": "v",
               "parts": {"body": {"slots": {"main": "matte"}}},
               "finishes": {"matte": {"version": "1"}}})
    }

    #[test]
    fn spec_view_ignores_what_the_approval_sets_and_binds_the_rest() {
        let plain = blender_draft_id(&spec());
        let mut flagged = spec();
        flagged["confirmed"] = json!(true);
        flagged["confirmed_by"] = json!("adrian");
        flagged["finishes"]["matte"]["approved"] = json!(true);
        flagged["finishes"]["matte"]["approved_by"] = json!("adrian");
        assert_eq!(
            blender_draft_id(&flagged),
            plain,
            "caller-set flags are not part of the inputs"
        );
        let mut edited = spec();
        edited["finishes"]["matte"]["version"] = json!("2");
        assert_ne!(
            blender_draft_id(&edited),
            plain,
            "a changed finish changes the draft id"
        );
    }

    #[test]
    fn receipt_needs_an_issued_and_consumed_challenge_for_these_inputs() {
        let dir = temp("receipt");
        let draft = blender_draft_id(&spec());
        let nonce = "ab".repeat(16);
        let record = json!({"kind": BLENDER_KIND, "nonce": nonce, "input_hash": draft, "channel": "sidecar_secret", "approved_at": "t"});
        assert!(
            !receipt_valid(&dir, BLENDER_KIND, &draft, &draft, &record),
            "a bare record has no challenge"
        );
        let file = challenge_file(&dir, BLENDER_KIND, &draft, &nonce).unwrap();
        std::fs::create_dir_all(file.parent().unwrap()).unwrap();
        std::fs::write(
            &file,
            json!({"nonce": nonce, "input_hash": draft}).to_string(),
        )
        .unwrap();
        assert!(
            !receipt_valid(&dir, BLENDER_KIND, &draft, &draft, &record),
            "an unconsumed challenge approves nothing"
        );
        std::fs::write(format!("{}.used", file.display()), "t").unwrap();
        assert!(receipt_valid(&dir, BLENDER_KIND, &draft, &draft, &record));
        let other = "c".repeat(64);
        assert!(
            !receipt_valid(&dir, BLENDER_KIND, &other, &other, &record),
            "another draft"
        );
        let mut wrong_hash = record.clone();
        wrong_hash["input_hash"] = json!(other);
        assert!(
            !receipt_valid(&dir, BLENDER_KIND, &draft, &draft, &wrong_hash),
            "another hash"
        );
        let mut wrong_nonce = record.clone();
        wrong_nonce["nonce"] = json!("../x");
        assert!(
            !receipt_valid(&dir, BLENDER_KIND, &draft, &draft, &wrong_nonce),
            "an unsafe nonce"
        );
        let mut wrong_kind = record.clone();
        wrong_kind["kind"] = json!("eyes");
        assert!(
            !receipt_valid(&dir, BLENDER_KIND, &draft, &draft, &wrong_kind),
            "another kind"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }
}
